  if (!explain) {
    return;
  }
  const toolbar = container.querySelector(".member-toolbar");
  const containerTop = container.getBoundingClientRect().top;
  const offset = (toolbar?.offsetHeight ?? 0) + 8;
  const top = explain.getBoundingClientRect().top;
